pub fn find_max(a: &[i32]) -> usize {
    // Since the slice is guaranteed to be non-empty, we can initialize
    // the maximum with the first element.
    let mut max_idx = 0;
    let mut max_val = a[0];

    // Iterate from the second element onward.
    for (i, &val) in a.iter().enumerate().skip(1) {
        if val > max_val {
            max_val = val;
            max_idx = i;
        }
    }

    max_idx
}

